import{_ as t,o as s,c as r,aN as o}from"./chunks/framework.D31DlcCL.js";const n="/img/math-graphic-equations.svg",d=JSON.parse('{"title":"图形会说话：图文算式中的代数奥秘","description":"当苹果、香蕉变成算式里的主角，数学就变成了一场有趣的“角色替换”游戏。","frontmatter":{"title":"图形会说话：图文算式中的代数奥秘","date":"2026-02-09T13:00:00.000Z","categories":["数学"],"tags":["小学数学","代数思维","图文算式"],"description":"当苹果、香蕉变成算式里的主角，数学就变成了一场有趣的“角色替换”游戏。","cover":"/img/math-graphic-equations.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-graphic-arithmetic.md","filePath":"posts/primary-math-graphic-arithmetic.md","lastUpdated":null}'),e={name:"posts/primary-math-graphic-arithmetic.md"};function i(l,a,p,m,h,c){return s(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="图形会说话-图文算式中的代数奥秘" tabindex="-1">图形会说话：图文算式中的代数奥秘 <a class="header-anchor" href="#图形会说话-图文算式中的代数奥秘" aria-label="Permalink to &quot;图形会说话：图文算式中的代数奥秘&quot;">​</a></h1><p>在数学的世界里，数字有时候会“变身”。它可能变成一个红彤彤的苹果，也可能变成一个调皮的小方块。</p><p>这就是**“图文算式”**。它是通往高级数学（代数）的秘密通道。</p><hr><h2 id="一、-核心法宝-等量代换" tabindex="-1">一、 核心法宝：等量代换 <a class="header-anchor" href="#一、-核心法宝-等量代换" aria-label="Permalink to &quot;一、 核心法宝：等量代换&quot;">​</a></h2><p>简单来说，就是“以物换物”。如果两个苹果等于 10，那么一个苹果就等于 5。</p><p><img src="'+n+'" alt="图文算式图解"></p><p><strong>【解题三部曲】</strong>：</p><ol><li><strong>找突破口</strong>：先看哪一行只有<strong>一种</strong>图形。</li><li><strong>算出一份</strong>：算出这个图形代表几。</li><li><strong>带入其他</strong>：把算出来的数字“变回去”，解决剩下的等式。</li></ol><hr><h2 id="二、-常见题型" tabindex="-1">二、 常见题型 <a class="header-anchor" href="#二、-常见题型" aria-label="Permalink to &quot;二、 常见题型&quot;">​</a></h2><h3 id="_1-孪生姐妹-型" tabindex="-1">1. “孪生姐妹”型 <a class="header-anchor" href="#_1-孪生姐妹-型" aria-label="Permalink to &quot;1. “孪生姐妹”型&quot;">​</a></h3><blockquote><p>○ + ○ = 12 这种最简单，想一想：哪两个一样的数相加等于 12？（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">6 + 6 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>）</p></blockquote><h3 id="_2-角色扮演-型" tabindex="-1">2. “角色扮演”型 <a class="header-anchor" href="#_2-角色扮演-型" aria-label="Permalink to &quot;2. “角色扮演”型&quot;">​</a></h3><blockquote><p>○ + ○ = 10 ○ + △ = 13 <strong>解析</strong>：先从第一行算出 ○ = 5。然后把 5 带入第二行：5 + △ = 13。所以 △ = 8。</p></blockquote><hr><h2 id="三、-经典例题-水果店的账单" tabindex="-1">三、 经典例题：水果店的账单 <a class="header-anchor" href="#三、-经典例题-水果店的账单" aria-label="Permalink to &quot;三、 经典例题：水果店的账单&quot;">​</a></h2><p><strong>题目</strong>：</p><ol><li>🍎 + 🍎 + 🍎 = 15</li><li>🍎 + 🍌 = 12</li><li>🍌 - 🍇 = 3 请问：🍇 代表几？</li></ol><p><strong>解析</strong>：</p><ol><li><strong>看第 1 行</strong>：三个苹果是 15，所以 1 个苹果 🍎 = 5。</li><li><strong>看第 2 行</strong>：5 + 🍌 = 12，所以 1 根香蕉 🍌 = 7。</li><li><strong>看第 3 行</strong>：7 - 🍇 = 3，所以 1 串葡萄 🍇 = 4。</li></ol><p><strong>答案</strong>：葡萄代表 4。</p><hr><h2 id="四、-避坑指南-看清符号" tabindex="-1">四、 避坑指南：看清符号 <a class="header-anchor" href="#四、-避坑指南-看清符号" aria-label="Permalink to &quot;四、 避坑指南：看清符号&quot;">​</a></h2><p>很多小朋友在做图文算式时，容易把“+”看成“-”，或者把“×”看成“+”。 还有一种高级陷阱：<strong>图形的数量</strong>。 比如：一行里是 3 根香蕉，下一行可能变成了 2 根。这时候要先算出一根代表几哦！</p><hr><h2 id="五、-练一练" tabindex="-1">五、 练一练 <a class="header-anchor" href="#五、-练一练" aria-label="Permalink to &quot;五、 练一练&quot;">​</a></h2><ol><li><p><strong>图形大作战</strong>：</p><ul><li>△ + △ = 16</li><li>△ + □ = 20</li><li>□ - ○ = 5 请问：○ = ?</li></ul></li><li><p><strong>水果谜题</strong>：</p><ul><li>2个草莓 = 1个梨</li><li>3个梨 = 12 请问：1个草莓等于几？</li></ul></li></ol><hr><p><em>总结：图文算式是数学里的“代号游戏”。学会了替换和代入，你就是未来的代数小天才！</em></p>',30)])])}const u=t(e,[["render",i]]);export{d as __pageData,u as default};
